input.command:
cd "D:\My Drive\Blue AI"
$dirs = @('agents', 'blueprints', 'daemons', 'graphify', 'graphify-out', 'memory', 'plugins', 'scripts', 'skills', 'temp', 'templates', 'worktrees')

foreach ($dir in $dirs) {
    $path = ".\.claude\$dir"
    if (Test-Path $path) {
        $files = Get-ChildItem -Path $path -Recurse -Force -File 2>$null
        $folders = Get-ChildItem -Path $path -Recurse -Force -Directory 2>$null
        $size = ($files | Measure-Object -Property Length -Sum).Sum / 1MB
        $fileCount = @($files).Count
        $folderCount = @($folders).Count
        Write-Host "$dir | Files: $fileCount | Folders: $folderCount | Size: $([math]::Round($size, 1))MB"
    }
}

