input.command:
cd "D:\My Drive\Blue AI"

# Check skills size breakdown
Write-Host "=== SKILLS - Size breakdown by folder ===" -ForegroundColor Green
Get-ChildItem -Path .\.claude\skills -Directory | ForEach-Object {
    $files = Get-ChildItem -Path $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue
    $size = ($files | Measure-Object -Property Length -Sum).Sum / 1MB
    $fileCount = @($files).Count
    [PSCustomObject]@{
        Name = $_.Name
        Files = $fileCount
        SizeMB = [math]::Round($size, 2)
    }
} | Sort-Object SizeMB -Descending | Select-Object -First 15 | Format-Table -AutoSize

